ni and Borromini"}, {"id": "3c970e1b-6dcf-4f96-b302-d75e97fe503b", "type": "concept", "title": "Urban scenography"}, {"id": "0bb380f1-d7a1-481d-8fb5-0c06bdf7cea1", "type": "concept", "title": "Church interiors"}], "description": "Students analyze movement, theatricality, urban axes, light, illusion, and Counter-Reformation patronage."}, {"id": "4c5c3fbd-da53-4912-af7a-a55c1b3c2143", "type": "subtopic", "title": "Early modern global encounters", "children": [{"id": "89fc95bb-0567-4031-b3e5-56821d1bf9b4", "type": "concept", "title": "Mission churches"}, {"id": "a55c63a8-a17a-4831-b183-110fc1bb0d97", "type": "concept", "title": "Trade networks"}, {"id": "0ec3d139-12ae-4ff7-90ff-3f838a16c045", "type": "concept", "title": "Colonial cities"}], "description": "The section traces colonial exchange, mission architecture, hybrid forms, and uneven power."}, {"id": "01640a52-92b0-4068-a761-a66299a696fd", "type": "subtopic", "title": "Synthesis and historiography", "children": [{"id": "02fb4096-9529-438b-a70f-808ce86c21c3", "type": "concept", "title": "Canon critique"}, {"id": "af67fab0-4af5-4bf3-8383-5601cee034f7", "type": "concept", "title": "Vernacular architecture"}, {"id": "43960a9a-82ab-4c97-9a42-cb44530b826e", "type": "concept", "title": "Final comparative argument"}], "description": "Students end by questioning canons, comparing traditions, and connecting history to preservation and design practice."}]}], "dbBacked": true}$ahi1json$::jsonb,
