update public.learning_paths
set
  title = 'Architectural History I',
  goal = 'Architectural History I',
  summary = 'Architectural History I surveys architecture from prehistory through the early modern period with a global and methodologically rigorous frame. Students learn to analyze buildings, cities, landscapes, drawings, materials, patrons, users, craft, construction systems, and historical texts. The course connects ancient, medieval, Islamic, South Asian, East Asian, Renaissance, Baroque, vernacular, and early global traditions to architectural design thinking.',
  data = $ahi1json${"slug": "architectural-history-i", "title": "Architectural History I", "description": "Architectural History I surveys architecture from prehistory through the early modern period with a global and methodologically rigorous frame. Students learn to analyze buildings, cities, landscapes, drawings, materials, patrons, users, craft, construction systems, and historical texts. The course connects ancient, medieval, Islamic, South Asian, East Asian, Renaissance, Baroque, vernacular, and early global traditions to architectural design thinking.", "topics": [{"id": "058def88-f6a7-4ae5-a143-4cc388b44aa1", "type": "topic", "title": "Methods of Architectural History: Buildings, Evidence, Style, and Context", "description": "This section develops architectural-historical knowledge through close looking, spatial analysis, material evidence, cultural context, and comparative interpretation.", "children": [{"id": "dd7ec873-3110-4540-9689-816fc32a1f7b", "type": "subtopic", "title": "Reading buildings as evidence", "children": [{"id": "fc372b11-d48d-457c-b2c2-76005869db69", "type": "concept", "title": "Plan, section, elevation, and site"}, {"id": "9efdd9e7-6670-4300-9918-61617963f0b5", "type": "concept", "title": "Material and construction clues"}, {"id": "6a2ca789-d499-4461-bce7-a1fac948bd6c", "type": "concept", "title": "Use, movement, and ritual"}], "description": "Students learn that buildings are historical documents made from space, form, structure, material, labor, and use."}, {"id": "f43d951b-c694-4255-8cf4-30645568ca61", "type": "subtopic", "title": "Style, typology, and chronology", "children": [{"id": "07999c18-a852-47f0-a58b-6b8d66d80fa3", "type": "concept", "title": "Formal vocabulary"}, {"id": "6e82708b-f416-4153-af40-372e08ad9129", "type": "concept", "title": "Building types"}, {"id": "79fad56a-7bde-4bdb-9f81-978568348878", "type": "concept", "title": "Periodization and its limits"}], "description": "This introduces style as a useful but limited tool for organizing historical change."}, {"id": "178ada97-02d6-4fb4-8218-f4d69d089cc2", "type": "subtopic", "title": "Context and interpretation", "children": [{"id": "cc2d7d73-b647-405a-885d-d081524eadd4", "type": "concept", "title": "Patron and user"}, {"id": "129f3441-601f-478c-a957-311e6a2d4aac", "type": "concept", "title": "Climate and resource systems"}, {"id": "5cd34e96-c6a5-42a1-a54d-6beebc7ca626", "type": "concept", "title": "Power and memory"}], "description": "Students connect buildings to patronage, economy, religion, politics, environment, gender, labor, and reception."}]}, {"id": "e1a037e3-0fc7-42b5-b835-e8a8281b7faf", "type": "topic", "title": "Prehistory, Megaliths, Vernacular Origins, and Early Settlement", "description": "This section develops architectural-historical knowledge through close looking, spatial analysis, material evidence, cultural context, and comparative interpretation.", "children": [{"id": "282752ae-992d-4160-9a9b-6c976c390d97", "type": "subtopic", "title": "Shelter and settlement", "children": [{"id": "b9c62fff-0511-4822-8d15-d590aaec3dd7", "type": "concept", "title": "Caves and shelters"}, {"id": "830b684a-d762-4e28-84ab-d6428c98c446", "type": "concept", "title": "Neolithic villages"}, {"id": "47da7941-eac3-4b24-b3e1-ea683a15fdce", "type": "concept", "title": "Agriculture and settlement"}], "description": "Students study how early built environments respond to climate, food systems, materials, and community organization."}, {"id": "a0d4201b-3d03-4180-89a6-f9c5238f1ac6", "type": "subtopic", "title": "Megaliths and ritual landscapes", "children": [{"id": "8960fa6a-5d44-41b1-95f0-09a568f28dde", "type": "concept", "title": "Stone circles"}, {"id": "1e64d8be-6a5d-4be2-8b56-99b0c45d771b", "type": "concept", "title": "Burial mounds"}, {"id": "69375f48-c975-4870-9684-aba6a1bda1de", "type": "concept", "title": "Astronomical alignment"}], "description": "The point is to see monumentality before formal states or written architectural theory."}, {"id": "82a36a88-4ee7-4ced-93b8-efb9d00eacd5", "type": "subtopic", "title": "Vernacular continuities", "children": [{"id": "3eff0dc6-ff5c-4325-a964-c2e62ebcf45c", "type": "concept", "title": "Local materials"}, {"id": "189dcb33-15e5-4b81-98ec-269e80fa887c", "type": "concept", "title": "Climate response"}, {"id": "fa428bb8-3222-44bf-acad-837fce533f0f", "type": "concept", "title": "Transmission of craft"}], "description": "Students learn to value ordinary building traditions, craft knowledge, and adaptation to local conditions."}]}, {"id": "4a22a26c-d443-4766-9df8-80ee81763da7", "type": "topic", "title": "Mesopotamia and Ancient Near Eastern Urbanism", "description": "This section develops architectural-historical knowledge through close looking, spatial analysis, material evidence, cultural context, and comparative interpretation.", "children": [{"id": "f471e828-0841-4fd2-ab0c-c9000fe79060", "type": "subtopic", "title": "City and temple", "children": [{"id": "225fd67d-2738-40cd-960e-89d1c7f8eaf3", "type": "concept", "title": "Uruk and Ur"}, {"id": "3c50e28d-c37b-4063-a79b-0682eed019f2", "type": "concept", "title": "Ziggurats"}, {"id": "84d31882-2dcd-48e5-b93a-d7c8bc1c9da8", "type": "concept", "title": "Sacred precincts"}], "description": "Students examine urban life as an architectural invention tied to surplus, writing, ritual, and administration."}, {"id": "96254a99-81c9-4192-8dce-8c288a393158", "type": "subtopic", "title": "Palace and power", "children": [{"id": "d59db872-3a56-40fe-916f-2f3ff350cfdd", "type": "concept", "title": "Assyrian palaces"}, {"id": "45416b87-5207-42dc-b447-687c2d1c761e", "type": "concept", "title": "Processional routes"}, {"id": "acf2dc80-c36b-46b9-9e40-20816b71c09b", "type": "concept", "title": "Relief and narrative"}], "description": "The section studies architecture as a tool of kingship, bureaucracy, display, and control."}, {"id": "b451d948-dd79-40df-8254-751fb369f7f7", "type": "subtopic", "title": "Materials and infrastructure"